int main(){using T=ks::SyncValueTask;using S=T::Stage;unsigned cases=0;for(unsigned kind=0;kind<2;++kind)for(unsigned input=0;input<256;++input)for(unsigned secondary=0;secondary<256;++secondary){T t(static_cast<T::Kind>(kind));unsigned used=0,dispatch=0,reads=0;uint32_t table=0x9a53c2f1u^(input*0x19471271u)^(secondary*0x42a71539u);while(t.stage()!=S::Complete){if(t.awaiting()){++dispatch;if(!t.resumeChild())throw std::runtime_error("resume");continue;}auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](T::Read){return 0;}))throw std::runtime_error("early");used+=t.advanceBefore(cost,[&](T::Read r)->uint32_t{++reads;if(r==T::Read::Table&&t.value()!=((input&1)*16|(secondary&12)))throw std::runtime_error("table index");return r==T::Read::Input?input:r==T::Read::Secondary?secondary:table;});}bool sends=kind?(input&6)==6:input!=0;unsigned clocks=kind?(sends?97u:29u):(sends?64u:23u);uint32_t wire=kind?table>>8:((input-1)&3)<<22;if(dispatch!=unsigned(sends)||used!=clocks||(sends&&t.wire()!=wire)||reads!=(kind?(sends?3u:1u):1u))throw std::runtime_error("result/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure sync-value properties\n";}
